// loft: a 30 x 10 rectangle to a 15 x 5 one 20 mm above, tangent to the start profile
export function c006(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "r", { "firstCorner" : vector(-15, -5) * millimeter, "secondCorner" : vector(15, 5) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s2, "r", { "firstCorner" : vector(-7.5, -2.5) * millimeter, "secondCorner" : vector(7.5, 2.5) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "startCondition" : LoftEndDerivativeType.TANGENT_TO_PROFILE, "startMagnitude" : 1 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}

// loft: a hexagon of radius 10 to one of radius 5 20 mm above, tangent to the start profile
export function c007(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s1, "line1", { "start" : vector(10, 0) * millimeter, "end" : vector(5, 8.660254) * millimeter });
    skLineSegment(s1, "line2", { "start" : vector(5, 8.660254) * millimeter, "end" : vector(-5, 8.660254) * millimeter });
    skLineSegment(s1, "line3", { "start" : vector(-5, 8.660254) * millimeter, "end" : vector(-10, 0) * millimeter });
    skLineSegment(s1, "line4", { "start" : vector(-10, 0) * millimeter, "end" : vector(-5, -8.660254) * millimeter });
    skLineSegment(s1, "line5", { "start" : vector(-5, -8.660254) * millimeter, "end" : vector(5, -8.660254) * millimeter });
    skLineSegment(s1, "line6", { "start" : vector(5, -8.660254) * millimeter, "end" : vector(10, 0) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s2, "line1", { "start" : vector(5, 0) * millimeter, "end" : vector(2.5, 4.330127) * millimeter });
    skLineSegment(s2, "line2", { "start" : vector(2.5, 4.330127) * millimeter, "end" : vector(-2.5, 4.330127) * millimeter });
    skLineSegment(s2, "line3", { "start" : vector(-2.5, 4.330127) * millimeter, "end" : vector(-5, 0) * millimeter });
    skLineSegment(s2, "line4", { "start" : vector(-5, 0) * millimeter, "end" : vector(-2.5, -4.330127) * millimeter });
    skLineSegment(s2, "line5", { "start" : vector(-2.5, -4.330127) * millimeter, "end" : vector(2.5, -4.330127) * millimeter });
    skLineSegment(s2, "line6", { "start" : vector(2.5, -4.330127) * millimeter, "end" : vector(5, 0) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "startCondition" : LoftEndDerivativeType.TANGENT_TO_PROFILE, "startMagnitude" : 1 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}

