// sheet-metal-flat: a plate with a flange, a 6 mm circle at (0, 0) cut in its flat pattern
export function c009(context is Context, id is Id)
{
    smBracket(context, id + "bracket");
    const f = newSketch(context, id + "f", { "sketchPlane" : qCorrespondingInFlat(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "bracketsm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 2) * millimeter)) });
    skCircle(f, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(f);
    const flatPlane = evPlane(context, { "face" : qCorrespondingInFlat(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "bracketsm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 2) * millimeter)) });
    extrude(context, id + "flat1", { "bodyType" : ExtendedToolBodyType.SOLID, "entities" : qSketchRegion(id + "f"), "domain" : OperationDomain.FLAT, "flatOperationType" : FlatOperationType.REMOVE, "endBound" : BoundingType.BLIND, "depth" : 2 * millimeter });
    return { "flatPlane" : { "origin" : round6(flatPlane.origin), "normal" : flatPlane.normal, "x" : flatPlane.x } };
}

